import * as M from './model.mjs';
import {LESSONS,SOURCES} from './lessons.mjs';
import {DATA,backtest} from '../chapter-08/model.mjs';
const CHAPTER=10,esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=M.restoreState(localStorage.getItem(M.STORAGE_KEY));}catch{state=M.freshState();}
let step=M.STEPS.some(x=>x[0]===location.hash.slice(1))?location.hash.slice(1):'start';
const $=s=>document.querySelector(s),announce=t=>{$('#announcement').textContent=t;};
function save(){state.done=M.completion(state);try{localStorage.setItem(M.STORAGE_KEY,JSON.stringify(state));$('#save-state').textContent='Saved on this device';}catch{$('#save-state').textContent='Storage unavailable: export before leaving';}progress();}
function progress(){state.done=M.completion(state);const count=Object.values(state.done).filter(Boolean).length;$('#progress').value=count;$('#progress-label').textContent=`${count} / 6 evidence steps · learner self-review` ;$('#navigation').innerHTML=M.STEPS.map(([id,title,min])=>`<a href="#${id}" ${id===step?'aria-current="step"':''}>${state.done[id]?'✓ ':''}${esc(title)} <small>${min} min</small></a>`).join('');}
const input=(id,label,type='text')=>`<label class="field" for="${id}">${label}</label><input id="${id}" data-field="${id}" type="${type}" value="${esc(state.fields[id]||'')}">`;
const text=(id,label,cls='')=>`<label class="field" for="${id}">${label}</label><textarea id="${id}" class="${cls}" data-field="${id}">${esc(state.fields[id]||'')}</textarea>`;
const tick=(id,label)=>`<label class="field"><input data-field="${id}" id="${id}" type="checkbox" ${state.fields[id]==='yes'?'checked':''}> ${label}</label>`;
const money=x=>Number(x).toFixed(4),pct=x=>(100*x).toFixed(4)+'%';
function table(run){return `<div class="table-wrap"><table><caption>Current frozen plan · synthetic evaluation · £1,000 initial</caption><thead><tr><th scope="col">Cost / notional</th><th scope="col">Strategy final (£)</th><th scope="col">Return</th><th scope="col">Benchmark final (£)</th><th scope="col">Return</th><th scope="col">Strategy maximum drawdown (%)</th><th scope="col">Benchmark maximum drawdown (%)</th></tr></thead><tbody>${[['10bps',run.base],['30bps',run.sensitivity]].map(([label,r])=>`<tr><th scope="row">${label}</th><td>${money(r.finalWealth)}</td><td>${pct(r.totalReturn)}</td><td>${money(r.benchmarkFinal)}</td><td>${pct(r.benchmarkReturn)}</td><td>${money(r.strategyMaxDrawdown)}</td><td>${money(r.benchmarkMaxDrawdown)}</td></tr>`).join('')}</tbody></table></div><p>Maximum drawdown is a positive loss magnitude:100×(1−wealth/runningpeak). Include initial£1,000, each period-end wealth and final liquidation. It is observed only at these boundaries, not an intraperiod or future loss bound. Costs may change both growth and drawdown; no annualisation is used.</p><p>${run.exploratory?'Exploratory: evaluation was already inspected under a different plan.':'Pedagogical frozen-plan evaluation; prior external/source inspection cannot be established by this browser.'}</p><details><summary>Row evidence and full input table</summary><p>First eligible signal ${esc(run.base.rows[0].signalDate)}; entry ${esc(run.base.rows[0].entryDate)}; last exit ${esc(run.base.rows.at(-1).exitDate)}. Final liquidation cost £${money(run.base.finalExitCost)}. Values below are not annualised.</p><div class="table-wrap"><table><caption>Base 10bps period ledger; terminal liquidation is additional</caption><thead><tr><th>Signal</th><th>Entry</th><th>Exit</th><th>Position</th><th>Turnover</th><th>Underlying open-to-open return</th><th>Start (£)</th><th>End (£)</th></tr></thead><tbody>${run.base.rows.map(r=>`<tr><td>${esc(r.signalDate)}</td><td>${esc(r.entryDate)}</td><td>${esc(r.exitDate)}</td><td>${r.position}</td><td>${r.turnover}</td><td>${pct(r.grossReturn)}</td><td>${money(r.startWealth)}</td><td>${money(r.endWealth)}</td></tr>`).join('')}</tbody></table></div><pre>${esc(JSON.stringify(M.EVALUATION_DATA,null,2))}</pre></details>`;}
function plan(){const p=M.currentPlan(state);return text('question','Testable question (30+ characters). Include any prior evaluation exposure.')+text('prediction','Prediction before this reveal (20+ characters; disclose if retrospective).')+'<button data-action="freeze">Freeze a new immutable plan version</button>'+`<p>${p?'Current frozen version '+p.plan.version:'Current inputs have no valid frozen plan. Editing makes earlier results stale.'}</p><details><summary>All frozen plan versions (${state.plans.length})</summary>${state.plans.map(p=>`<pre>${esc(JSON.stringify(p,null,2))}</pre>`).join('')}</details>`;}
function results(){const r=M.latestEvidence(state);return '<button data-action="run">Reveal / reproduce both predefined cost cases</button>'+ (r?table(r)+input('hand','Calculate first-row end wealth independently (£, tolerance .01).','number')+'<button data-action="hand">Check hand calculation</button>':'<p>Freeze current inputs before reveal. Old runs remain in the export but do not satisfy current evidence.</p>')+`<details><summary>All retained evaluation trials (${state.runs.length})</summary>${state.runs.map((r,i)=>`<p>Run ${i+1}, plan v${r.planVersion}, ${esc(r.time)}: 10bps £${money(r.base.finalWealth)}; 30bps £${money(r.sensitivity.finalWealth)}${r.exploratory?' · exploratory':''}.</p>`).join('')}</details>`;}
function render(){progress();let extra='';if(step==='start')extra=tick('setup','I understand the standalone path, synthetic source, local record and unvalidated self-review status.');if(step==='plan'){if(!state.fields.question&&!state.plans.length){state.fields.question='Does the fixed three-close rule improve the observed trade-off versus same-period net buy-and-hold on the synthetic evaluation block?';state.fields.prediction='Before reveal I predict that higher costs will reduce both net results; any prior inspection must be disclosed here.';}extra=plan();}if(step==='evidence')extra=results();if(step==='memo')extra=text('memo','Research memo: 600–800 words, supported by exported evidence attachment.','memo-editor')+`<p id="word-count">${M.wordCount(state.fields.memo||'')} words · length does not judge quality</p>`;if(step==='review')extra='<fieldset><legend>Critical integrity criteria — all required</legend>'+M.CRITICAL.map(([id,label])=>tick('critical-'+id,label)).join('')+'</fieldset>'+M.RUBRIC.map(q=>`<div class="record"><h2>${esc(q.title)} (${q.weight} points)</h2><p>${esc(q.anchors)}</p>${input(q.id,'Your self-assessed score (0–'+q.weight+').','number')}</div>`).join('')+text('reviewNote','Cite criterion evidence and a concrete weakness or verification (60+ characters).')+'<button data-action="review">Record current draft self-review</button>'+`<p>${state.reviews.length} self-review attempts retained. Scores are learner judgments, not validated marks.</p>`;if(step==='finish')extra=text('revisionNote','After editing your memo, explain the specific revision, criterion and evidence (60+ characters).')+'<button data-action="revision">Record revised memo and readiness check</button><button data-action="memo-download" class="secondary">Download current memo text</button>'+`<p>${state.revisions.length} revision attempts retained. Current readiness: ${M.revisionValid(state)?'self-reviewed submission recorded':'not yet recorded; review current evidence, then change memo and record revision'}.</p>`;const i=M.STEPS.findIndex(x=>x[0]===step);$('#lesson').innerHTML=`<article>${LESSONS[step]}<div class="panel">${extra}</div><div id="feedback" role="status" aria-live="polite"></div><div class="actions"><button data-action="save">Save / verify current step</button>${i?`<a class="button secondary" href="#${M.STEPS[i-1][0]}">Back</a>`:''}${i<5?`<a class="button" href="#${M.STEPS[i+1][0]}">Continue</a>`:''}</div><details><summary>Sources and limits</summary><p>Original synthetic tasks/data; checked 31 October 2026. Local freezing is not external registry preregistration. Repeated selection can overfit; one held-out segment does not eliminate it.</p>${SOURCES.map(([t,u])=>`<p><a href="${u}">${esc(t)}</a></p>`).join('')}<p><a href="https://www.cos.io/initiatives/prereg">Center for Open Science: preregistration</a></p><p>Human timing, assistive technology and educational-effectiveness testing remain outstanding. No automatic course credential.</p></details></article>`;}

function feedback(t){$('#feedback').textContent=t;announce(t);}
document.addEventListener('input',e=>{const id=e.target.dataset.field;if(!id)return;if(['question','prediction'].includes(id)){state.fields.integrity='';state.fields.selfReview='';state.fields.hand='';}state.fields[id]=e.target.type==='checkbox'?(e.target.checked?'yes':''):e.target.value;if(id==='memo'&&$('#word-count'))$('#word-count').textContent=M.wordCount(e.target.value)+' words · length does not judge quality';save();});
document.addEventListener('click',e=>{if(e.target.closest('a.skip')){e.preventDefault();$('#lesson').focus();return;}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;try{if(action==='privacy')return $('#privacy-dialog').showModal();if(action==='close')return $('#privacy-dialog').close();if(action==='reset'){if(!confirm('Delete only this chapter’s local record? Downloaded files remain.'))return;localStorage.removeItem(M.STORAGE_KEY);state=M.freshState();$('#privacy-dialog').close();render();return;}if(action==='export'){const blob=new Blob([JSON.stringify({...state,data:M.EVALUATION_DATA,dataset:M.EVALUATION_ID},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='chapter-10-evidence.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}if(action==='review'){const review=M.selfReview(state);save();render();feedback('Self-review recorded: '+review.score+'/100. Revise the memo itself, then record its revision. This score is not independently validated.');return;}if(action==='revision'){M.saveRevision(state);save();render();feedback('Revised submission recorded. Export the full evidence and memo; this is learner self-assessment, not a course credential.');return;}if(action==='memo-download'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([state.fields.memo||''],{type:'text/plain'}));a.download='capstone-memo.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);return;}if(action==='freeze'){M.freeze(state);save();render();feedback('Plan frozen. Any earlier inspection must be disclosed; this is not external preregistration.');return;}if(action==='run'){M.evaluate(state);save();render();feedback('Both predefined cost trials retained. Inspect rows, hand-check and qualify the conclusion.');return;}if(action==='audit'){const grades=M.auditGrade(state.fields);state.attempts.push({time:new Date().toISOString(),fields:{...state.fields},grades});save();feedback(M.AUDIT.map((q,i)=>`${q.id}: ${grades[i].correct?'correct':'revisit — '+q.hint}`).join(' | '));return;}if(action==='hand'){const r=M.latestEvidence(state);if(!r)throw Error('Run the current plan first.');feedback(String(state.fields.hand??'').trim()!==''&&Math.abs(Number(state.fields.hand)-r.base.rows[0].endWealth)<.011?'Hand calculation matches. Explain the cost and holding interval in your memo.':'Revisit start × (1 − turnover × bps/10,000) × market factor. Read first-row opens in CSV; do not charge future returns.');return;}save();feedback(state.done[step]?'Current step evidence recorded. Prose correctness is self-reviewed; export for review.':'More evidence needed: check answers, current frozen inputs, required explanation and criteria. See text guide for the full key.');}catch(error){save();feedback(error.message);}});
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(M.STEPS.some(x=>x[0]===next)){step=next;render();$('#lesson').focus();}});render();
